import React, { useState, useEffect, useMemo } from 'react';
import { AgGridReact } from 'ag-grid-react';
import 'ag-grid-community/styles/ag-grid.css';
import 'ag-grid-community/styles/ag-theme-alpine.css';
import { searchTracks, getTrackDetails } from '../services/api';

const TrackSearch = ({ searchTerm }) => {
  const [filteredTracks, setFilteredTracks] = useState([]);
  const [trackDetails, setTrackDetails] = useState({});

  useEffect(() => {
    if (searchTerm) {
      searchTracks(searchTerm).then(async tracks => {
        setFilteredTracks(tracks);

        const detailsPromises = tracks.map(track =>
          getTrackDetails(track.id).then(details => ({ [track.id]: details }))
        );
        const detailsArray = await Promise.all(detailsPromises);
        setTrackDetails(Object.assign({}, ...detailsArray));
      }).catch(error => console.error('Error fetching tracks:', error));
    }
  }, [searchTerm]);

  const columns = useMemo(() => [
    { headerName: 'Track Name', field: 'name', minWidth: 80, sortable: true, filter: true, resizable: true },
    { headerName: 'Artist Name', field: 'artists[0].name', minWidth: 80, sortable: true, filter: true, resizable: true },
    { headerName: 'Album Name', field: 'album.name', minWidth: 80, sortable: true, filter: true, resizable: true },
    { headerName: 'Release Date', field: 'album.release_date', minWidth: 80, sortable: true, filter: true, resizable: true, 
      valueGetter: params => params.data.album.release_date ? params.data.album.release_date.split('-')[0] : 'Unknown' 
    },
    { headerName: 'Tempo', field: 'tempo', minWidth: 80, valueGetter: params => trackDetails[params.data.id]?.tempo || '', resizable: true },
    { headerName: 'Key', field: 'key', minWidth: 80, valueGetter: params => trackDetails[params.data.id]?.key || '', resizable: true },
    { headerName: 'Danceability', field: 'danceability', minWidth: 80, valueGetter: params => trackDetails[params.data.id]?.danceability || '', resizable: true },
    { headerName: 'Energy', field: 'energy', minWidth: 80, valueGetter: params => trackDetails[params.data.id]?.energy || '', resizable: true },
    { headerName: 'Valence', field: 'valence', minWidth: 80, valueGetter: params => trackDetails[params.data.id]?.valence || '', resizable: true },
    { headerName: 'Acousticness', field: 'acousticness', minWidth: 80, valueGetter: params => trackDetails[params.data.id]?.acousticness || '', resizable: true },
    { headerName: 'Instrumentalness', field: 'instrumentalness', minWidth: 80, valueGetter: params => trackDetails[params.data.id]?.instrumentalness || '', resizable: true },
    { headerName: 'Liveness', field: 'liveness', minWidth: 80, valueGetter: params => trackDetails[params.data.id]?.liveness || '', resizable: true },
    { headerName: 'Genre', field: 'genres', minWidth: 100, valueGetter: params => trackDetails[params.data.id]?.genres?.join(', ') || '', resizable: true },
    {
      headerName: 'Preview',
      field: 'preview',
      minWidth: 240,
      cellRendererFramework: params => params.data.id ? (
        <iframe
          src={`https://open.spotify.com/embed/track/${params.data.id}`}
          width="100%"
          height="80"
          allow="encrypted-media"
          style={{ border: 'none' }}
        ></iframe>
      ) : 'No Preview'
    },
  ], [trackDetails]);

  return (
    <div className="ag-theme-alpine" style={{ height: '500px', width: '100%', marginTop: '20px' }}>
      <AgGridReact
        rowData={filteredTracks}
        columnDefs={columns}
        defaultColDef={{
          sortable: true,
          filter: true,
          resizable: true,
          minWidth: 80,
        }}
        domLayout="autoHeight"
      />
    </div>
  );
};

export default TrackSearch;
